package org.kanger;
import java.util.*;
import org.kanger.enums.QueryPass;
import org.kanger.ContextProductionCapture.*;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextUniversalFrozenConstraints.Proof;
import org.kanger.ContextUniversalFrozenConstraints.Result;
import org.kanger.ContextUniversalInputResiduals.Residual;
import org.kanger.ContextWitnessResultTransport.*;

/** Native mixed-donor observations expose an open grade obligation, never admission authority. */
public final class ContextUniversalSymbolicDonorEvidenceRunner {
    static int checks;static final int WORK=64000000;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static Snapshot bind(boolean x,String s)throws Exception{return ContextPrivateWitnessPoolRunner.bind(x,s);}
    static Result close(Snapshot x,Snapshot a,Packet p){ContextUniversalNativeRows.Result rows=ContextUniversalNativeRows.inspect(x,a,64,WORK);require(rows.classified&&rows.withinShape,rows.reason);Result r=ContextUniversalFrozenConstraints.closeSignedSymbolicHeads(rows,p,null,null,16,16,512,256,WORK);require(r.closed&&!r.xRefuted&&!r.foreignRefuted,r.reason);ContextUniversalFrozenConstraints.check(r,16,()->{});return r;}
    static ContextProductionCapture.Snapshot observe(String[] text,Source[] sources,int[] order)throws Exception {
        User user=new User();Mind m=new Mind(user);user.setCurrentMind(m);try(ContextProductionCapture c=ContextProductionCapture.begin(m,10000)){c.observeSchemaInteractions();for(int i:order)c.replay(m,sources[i],text[i]);m.setQueryPass(QueryPass.ACCEPT);m.link(null,false);return c.snapshot();}
    }
    static void gaps(ContextProductionCapture.Snapshot o){require(o.schemaInteractionsObserved&&!o.schemaInteractionsMissed&&!o.schemaInteractions.isEmpty(),"actual schema encounters captured before replay");require(!o.gaps.isEmpty()&&o.gaps.stream().allMatch(s->s.startsWith("unbound-waiter-composition:")),"schema observer retains unresolved native capture gaps");for(String s:o.gaps){long id=Long.parseLong(s.substring(s.indexOf(':')+1));require(o.schemaInteractions.stream().anyMatch(e->e.partnerRule==id),"each schema gap has actual encounter metadata");}}
    static void mixed(String rule,String universal,String fixed,String output,boolean sign,int permutations)throws Exception {
        Snapshot x=bind(true,universal+fixed),a=bind(false,rule);Packet p=ContextPrivateWitnessPoolRunner.common(x);Result r=close(x,a,p);List<Proof> products=new ArrayList<>();for(Proof v:r.proofs)if(v.clause!=null&&v.clause.literals.size()==1&&v.clause.literals.get(0).predicate.equals(output)&&v.clause.literals.get(0).positive==sign)products.add(v);
        require(products.size()==1,"one current exact-Source output alternative");Proof out=products.get(0);Source rs=ContextPrivateWitnessPoolRunner.source(a,rule),us=ContextPrivateWitnessPoolRunner.source(x,universal),fs=ContextPrivateWitnessPoolRunner.source(x,fixed);Set<Source> expected=new HashSet<>(Arrays.asList(rs,us,fs));require(out.clause.variables.isEmpty()&&out.support.depth==2&&out.support.sources.equals(expected)&&out.producer==null&&!out.symbolicHeadRecipe,"current symbolic donor route is a genuine binary2 proof with whole Sources");
        Proof unit=r.proofs.stream().filter(v->v.original!=null&&v.support.sources.equals(Collections.singleton(us))).findFirst().get();require(unit.clause.variables.size()>0,"actual symbolic unit original");
        String[] text={rule,universal,fixed};Source[] sources={rs,us,fs};int[][] orders={{0,1,2},{0,2,1},{1,0,2},{1,2,0},{2,0,1},{2,1,0}};
        for(int k=0;k<permutations;++k){ContextProductionCapture.Snapshot o=observe(text,sources,orders[k]);gaps(o);List<Application> events=new ArrayList<>();for(Application e:o.applications)if(e.conclusion.predicate.equals(output)&&e.conclusion.positive==sign)events.add(e);require(!events.isEmpty(),"actual native mixed-donor result observed");
            for(Application e:events){require(e.steps==1&&e.premises.size()==2&&out.clause.equivalent(ContextUniversalInputResiduals.fact(e.conclusion,()->{}),()->{}),"same concrete native output, real two-donor step1 vs checked binary2");require(e.producerSupports.stream().anyMatch(s->s.depth==0&&s.sources.equals(Collections.singleton(rs))),"actual producer retains original Source0");
                Application instance=o.applications.stream().filter(v->v.steps==0&&v.premises.isEmpty()&&v.producerSupports.stream().anyMatch(s->s.depth==0&&s.sources.equals(Collections.singleton(us)))&&ContextUniversalInputResiduals.instance(unit.clause,ContextUniversalInputResiduals.fact(v.conclusion,()->{}),()->{})&&e.premises.stream().anyMatch(f->f.equivalent(v.conclusion))).findFirst().orElse(null);require(instance!=null,"actual universal unit instance0 used by the actual donor group");
                require(e.premises.stream().anyMatch(f->p.items.stream().anyMatch(i->i.proofs.stream().anyMatch(s->s.depth==0&&s.sources.equals(Collections.singleton(fs)))&&ContextUniversalInputResiduals.fact(i,()->{}).equivalent(ContextUniversalInputResiduals.fact(f,()->{}),()->{}))),"other actual donor is the exact carried fixed Source0");
                Set<Source> nativeSources=new HashSet<>();nativeSources.addAll(e.producerSupports.get(0).sources);nativeSources.addAll(instance.producerSupports.get(0).sources);nativeSources.add(fs);require(nativeSources.equals(out.support.sources),"same full physical Source set at native1 and binary2");
            }
        }
        ConstraintTransfer denied=ContextWitnessResultTransport.transferConstraints(r,p,1,WORK);require(!denied.transferred&&denied.output==null,"current fact1 refuses, never admits incomplete grade coverage");ConstraintTransfer allowed=ContextWitnessResultTransport.transferConstraints(r,p,2,WORK);require(allowed.transferred&&ContextUniversalSignedProductAudit.bind(r,allowed,65536,WORK).bound,"current fact2 projection stays internally checked");
        ContextUniversalSignedUnitRounds.Result round=ContextUniversalSignedUnitRounds.runSymbolicHeads(x,Collections.singletonList(a),p,Collections.emptyMap(),null,ContextUniversalSymbolicHeadRoundsRunner.limits(1),8,WORK);require(round.status==ContextUniversalSignedUnitRounds.Status.INCOMPLETE&&round.phase.equals("transfers")&&round.completedRounds==0&&round.output==null&&round.history.isEmpty()&&round.refutations.isEmpty(),"integrated fact1 refusal is atomic; this is an open completeness obligation, not a false admission");
    }
    static void allSymbolic()throws Exception {
        for(String sign:Arrays.asList("","~")){String rule="!@x p(x)&&q(x)->"+sign+"r(x);",pu="!@u p(u);",qu="!@v q(v);";Snapshot x=bind(true,"!anchor(1);"+pu+qu),a=bind(false,rule);Packet p=ContextPrivateWitnessPoolRunner.common(x);Result r=close(x,a,p);Proof out=r.proofs.stream().filter(v->v.clause!=null&&v.clause.literals.size()==1&&v.clause.literals.get(0).predicate.equals("r")).findFirst().get();require(out.support.depth==2&&out.clause.variables.size()==1&&out.producer==null,"current all-symbolic result remains binary universal2");ContextProductionCapture.Snapshot o=observe(new String[]{rule,pu,qu},new Source[]{ContextPrivateWitnessPoolRunner.source(a,rule),ContextPrivateWitnessPoolRunner.source(x,pu),ContextPrivateWitnessPoolRunner.source(x,qu)},new int[]{0,1,2});gaps(o);require(o.applications.stream().noneMatch(e->e.conclusion.predicate.equals("r"))&&o.residuals.stream().noneMatch(e->e.conclusion.literals.size()==1&&e.conclusion.literals.get(0).predicate.equals("r")),"this native traversal observes no complete all-symbolic r application/residual; NOT proof of non-derivability");}
    }
    static void incompatible()throws Exception {
        String rule="!@x p(x,2)&&q(x)->r(x);",universal="!@u p(u,u);",fixed="!q(1);";Snapshot x=bind(true,universal+fixed),a=bind(false,rule);Result r=close(x,a,ContextPrivateWitnessPoolRunner.common(x));require(r.proofs.stream().noneMatch(v->v.clause!=null&&v.clause.literals.size()==1&&v.clause.literals.get(0).predicate.equals("r")),"one shared binding forbids inconsistent diagonal donor");ContextProductionCapture.Snapshot o=observe(new String[]{rule,universal,fixed},new Source[]{ContextPrivateWitnessPoolRunner.source(a,rule),ContextPrivateWitnessPoolRunner.source(x,universal),ContextPrivateWitnessPoolRunner.source(x,fixed)},new int[]{0,1,2});require(o.applications.stream().noneMatch(e->e.conclusion.predicate.equals("r")),"native inconsistent binding does not produce r");}
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("symbolic-donor-evidence-").toString());mixed("!@x p(x)&&q(x)->r(x);","!@u p(u);","!q(1);","r",true,6);mixed("!@x p(x)&&q(x)->~r(x);","!@u p(u);","!q(1);","r",false,2);mixed("!@x left(x)&&right(x)->p(x);","!@u ~p(u);","!right(1);","left",false,2);mixed("!@x p(x,x)&&q(x)->r(x);","!@u @v p(u,v);","!q(1);","r",true,2);allSymbolic();incompatible();System.out.println("CONTEXT_UNIVERSAL_SYMBOLIC_DONOR_EVIDENCE_PASS checks="+checks);System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
